<?php declare(strict_types=1);$pageTitle='Публикации';require_once __DIR__.'/_header.php';$posts=db()->query("SELECT p.id,p.title,p.slug,p.status,p.is_featured,p.published_at,p.updated_at,c.name category_name FROM posts p LEFT JOIN categories c ON c.id=p.category_id ORDER BY p.updated_at DESC")->fetchAll();$m=flash('success');?><?php if($m):?><div class="alert alert-success"><?=e($m)?></div><?php endif;?><div class="actions"><a class="btn" href="<?=e(url('admin/post-form.php'))?>">+ Создать новость</a></div><div style="overflow-x:auto;margin-top:16px"><table class="admin-table"><thead><tr><th>Заголовок</th><th>Рубрика</th><th>Статус</th><th>Главная</th><th>Публикация</th><th>Действия</th></tr></thead><tbody><?php foreach($posts as $p):?><tr><td><strong><?=e($p['title'])?></strong></td><td><?=e($p['category_name']??'—')?></td><td><?=e($p['status'])?></td><td><?=$p['is_featured']?'★':'—'?></td><td><?=$p['published_at']?e(format_date($p['published_at'])):'—'?></td><td><div class="actions"><a class="btn btn-secondary" href="<?=e(url('admin/post-form.php?id='.$p['id']))?>">Править</a><?php if($p['status']==='published'):?><a class="btn btn-secondary" target="_blank" href="<?=e(url('article.php?slug='.urlencode($p['slug'])))?>">Смотреть</a><?php endif;?><form method="post" action="<?=e(url('admin/delete-post.php'))?>" data-confirm-delete><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$p['id']?>"><button class="btn btn-danger">Удалить</button></form></div></td></tr><?php endforeach;?></tbody></table></div><?php require_once __DIR__.'/_footer.php';?>
